// Validate every extracted record. Never stop execution: invalid items
// become error objects, valid items get a methodology_score attached.

const VALID_STANCES = ['supports', 'contradicts', 'neutral', 'mixed'];

const METHODOLOGY_SCORES = {
  randomized_trial: 95,
  meta_analysis: 92,
  longitudinal: 85,
  cross_sectional: 60,
  animal_study: 40,
  opinion_review: 10,
  other: 30,
};

const results = [];

for (const item of $input.all()) {
  const d = item.json || {};
  const errors = [];

  // paper_id must exist
  if (d.paper_id === undefined || d.paper_id === null || String(d.paper_id).trim() === '') {
    errors.push('paper_id is missing');
  }

  // claim cannot be empty
  if (typeof d.claim !== 'string' || d.claim.trim() === '') {
    errors.push('claim is empty');
  }

  // stance must be one of the allowed values
  if (!VALID_STANCES.includes(d.stance)) {
    errors.push('stance must be one of: ' + VALID_STANCES.join(', '));
  }

  // confidence must be a number between 0 and 1 (inclusive)
  const conf = typeof d.confidence === 'number' ? d.confidence : Number(d.confidence);
  if (!Number.isFinite(conf) || conf < 0 || conf > 1) {
    errors.push('confidence must be a number between 0 and 1');
  }

  // methodology_type must be one of the allowed values
  const hasValidMethodology = Object.prototype.hasOwnProperty.call(
    METHODOLOGY_SCORES,
    d.methodology_type,
  );
  if (!hasValidMethodology) {
    errors.push('methodology_type must be one of: ' + Object.keys(METHODOLOGY_SCORES).join(', '));
  }

  if (errors.length > 0) {
    // Return an error object; do not stop execution.
    results.push({
      json: {
        valid: false,
        paper_id: d.paper_id !== undefined ? d.paper_id : null,
        errors,
        original: d,
      },
    });
    continue;
  }

  // Valid record: attach methodology_score.
  results.push({
    json: {
      valid: true,
      ...d,
      confidence: conf,
      methodology_score: METHODOLOGY_SCORES[d.methodology_type],
    },
  });
}

return results;
